            user = eval(line)
            skill_ids = json.loads(user.get('skill_ids_json', '{}'))
            if 'state-shopping' in skill_ids and user.get('loyalty_tier') == 'platinum':
                platinum_shopping_users.append(user)
        except:
            pass

